#[no_mangle]
pub unsafe extern "C" fn maximal_square(a:*const i64,len:usize)->i64{if a.is_null()||len<3||len>258{return -1}let v=std::slice::from_raw_parts(a,len);if !(1..=16).contains(&v[0])||!(1..=16).contains(&v[1])||v.len()!=v[0] as usize*v[1] as usize+2||v[2..].iter().any(|&x|x!=0&&x!=1){return -1}let(rows,cols)=(v[0]as usize,v[1]as usize);let mut dp=[0usize;16];let mut best=0;for r in 0..rows{let mut diag=0;for c in 0..cols{let above=dp[c];if v[r*cols+c+2]==1{dp[c]=if r==0||c==0{1}else{diag.min(dp[c]).min(dp[c-1])+1};best=best.max(dp[c]);}else{dp[c]=0}diag=above;}}(best*best)as i64}
